import requests

def fetch_text(s3url):
    b=requests.get(s3url,timeout=15).content
    if b[:2] in (b'\xff\xfe',b'\xfe\xff'):
        return b.decode('utf-16',errors='replace')
    return b.decode('utf-8-sig',errors='replace')
